-- chair-step: inverse of read_lane_v2_b3_42_communication_notification — un-enrolls communication.notification from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'communication' and table_name = 'notification' and is_active);
select iam.apply_rls('communication', 'notification', (select token from platform.entity_types where schema_name = 'communication' and table_name = 'notification' and is_active), (select rls_variant from platform.entity_types where schema_name = 'communication' and table_name = 'notification' and is_active));
